```ts
declare const tools: { web__run(args: {
  // Open links from previously opened pages.
  click?: Array<{
  // Numbered link id to open.
  id: number;
  // Reference id containing the numbered link.
  ref_id: string;
}>;
  // Look up prices for the given stock symbols.
  finance?: Array<{
  // ISO 3166-1 alpha-3 country code, "OTC", or "" for cryptocurrency.
  market?: string;
  // Ticker symbol to look up.
  ticker: string;
  // Asset type to look up.
  type: "equity" | "fund" | "crypto" | "index";
}>;
  // Find text patterns in pages.
  find?: Array<{
  // Text pattern to find.
  pattern: string;
  // Reference id or URL to search within.
  ref_id: string;
}>;
  // Query the image search engine for a given list of queries.
  image_query?: Array<{
  // Whether to filter by a specific list of domains.
  domains?: Array<string>;
  // Search query.
  q: string;
  // Whether to filter by recency, as a number of recent days.
  recency?: number;
}>;
  // Open pages by reference id or URL.
  open?: Array<{
  // Line number to position the page at.
  lineno?: number;
  // Reference id or URL to open.
  ref_id: string;
}>;
  // Set the length of the response to be returned.
  response_length?: "short" | "medium" | "long";
  // Take screenshots of PDF pages.
  screenshot?: Array<{
  // Zero-indexed PDF page number.
  pageno: number;
  // Reference id or URL to screenshot.
  ref_id: string;
}>;
  // Query the internet search engine for a given list of queries.
  search_query?: Array<{
  // Whether to filter by a specific list of domains.
  domains?: Array<string>;
  // Search query.
  q: string;
  // Whether to filter by recency, as a number of recent days.
  recency?: number;
}>;
  // Look up sports schedules and standings.
  sports?: Array<{
  // Start date in YYYY-MM-DD format.
  date_from?: string;
  // End date in YYYY-MM-DD format.
  date_to?: string;
  // Sports function to call.
  fn: "schedule" | "standings";
  // League to look up.
  league: "nba" | "wnba" | "nfl" | "nhl" | "mlb" | "epl" | "ncaamb" | "ncaawb" | "ipl";
  // Locale for the lookup.
  locale?: string;
  // Number of games to return.
  num_games?: number;
  // Opponent to use with `team` when narrowing the lookup.
  opponent?: string;
  // Team to look up, using the common 3 or 4 letter alias used in broadcasts.
  team?: string;
  // Tool name for sports requests.
  tool?: "sports";
}>;
  // Get time for the given UTC offsets.
  time?: Array<{
  // UTC offset formatted like "+03:00".
  utc_offset: string;
}>;
  // Look up weather forecasts.
  weather?: Array<{
  // Number of days to return. Defaults to 7.
  duration?: number;
  // Location in "Country, Area, City" format.
  location: string;
  // Start date in YYYY-MM-DD format. Defaults to today.
  start?: string;
}>;
}): Promise<unknown>; };
```

output.text:
name: NW.js Release

on:
  workflow_dispatch:
    inputs:
      tag:
        description: "Release tag to create or update. Defaults to v<VERSION>."
        required: false
        type: string
  push:
    tags:
      - "v*"

permissions:
  contents: write

env:
  NWJS_VERSION: "0.110.0"

jobs:
  package:
    name: Package Desktop Runtimes
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
        with:
          submodules: recursive

      - uses: denoland/setup-deno@v2
        with:
          deno-version: v2.x

      - name: Resolve Versions
        id: versions
        run: |
          app_version="$(tr -d '[:space:]' < VERSION)"
          if [ -n "${{ inputs.tag }}" ]; then
            release_tag="${{ inputs.tag }}"
          elif [ "${GITHUB_REF_TYPE}" = "tag" ]; then
            release_tag="${GITHUB_REF_NAME}"
          else
            release_tag="v${app_version}"
          fi
          echo "app_version=${app_version}" >> "$GITHUB_OUTPUT"
          echo "release_tag=${release_tag}" >> "$GITHUB_OUTPUT"

      - name: Download NW.js Runtimes
        run: |
          mkdir -p dist/nwjs-cache/downloads
          curl -L --fail --show-error \
            "https://dl.nwjs.io/v${NWJS_VERSION}/nwjs-v${NWJS_VERSION}-linux-x64.tar.gz" \
            -o "dist/nwjs-cache/downloads/nwjs-v${NWJS_VERSION}-linux-x64.tar.gz"
          curl -L --fail --show-error \
            "https://dl.nwjs.io/v${NWJS_VERSION}/nwjs-v${NWJS_VERSION}-win-x64.zip" \
            -o "dist/nwjs-cache/downloads/nwjs-v${NWJS_VERSION}-win-x64.zip"
          curl -L --fail --show-error \
            "https://dl.nwjs.io/v${NWJS_VERSION}/nwjs-v${NWJS_VERSION}-osx-arm64.zip" \
            -o "dist/nwjs-cache/downloads/nwjs-v${NWJS_VERSION}-osx-arm64.zip"

      - name: Extract NW.js Runtimes
        run: |
          mkdir -p \
            dist/nwjs-cache/runtimes/linux-x64 \
            dist/nwjs-cache/runtimes/win-x64 \
            dist/nwjs-cache/runtimes/osx-arm64
          tar -xzf "dist/nwjs-cache/downloads/nwjs-v${NWJS_VERSION}-linux-x64.tar.gz" \
            -C dist/nwjs-cache/runtimes/linux-x64
          unzip -q "dist/nwjs-cache/downloads/nwjs-v${NWJS_VERSION}-win-x64.zip" \
            -d dist/nwjs-cache/runtimes/win-x64
          unzip -q "dist/nwjs-cache/downloads/nwjs-v${NWJS_VERSION}-osx-arm64.zip" \
            -d dist/nwjs-cache/runtimes/osx-arm64

      - name: Build Source Zip
        run: |
          app_version="${{ steps.versions.outputs.app_version }}"
          deno task wrap:nwjs --out dist/jshack-app
          (
            cd dist/jshack-app
            zip -qry "../jshack-v${app_version}.zip" app
          )

      - name: Build Runtime Bundles
        run: |
          deno task wrap:nwjs \
            --out dist/jshack-nwjs-linux-x64 \
            --runtime "dist/nwjs-cache/runtimes/linux-x64/nwjs-v${NWJS_VERSION}-linux-x64"
          deno task wrap:nwjs \
            --out dist/jshack-nwjs-win-x64 \
            --runtime "dist/nwjs-cache/runtimes/win-x64/nwjs-v${NWJS_VERSION}-win-x64"
          deno task wrap:nwjs \
            --out dist/jshack-nwjs-osx-arm64 \
            --runtime "dist/nwjs-cache/runtimes/osx-arm64/nwjs-v${NWJS_VERSION}-osx-arm64"

      - name: Archive Bundles
        run: |
          app_version="${{ steps.versions.outputs.app_version }}"
          tar -czf "dist/jshack-nwjs-v${app_version}-linux-x64.tar.gz" \
            -C dist jshack-nwjs-linux-x64
          (
            cd dist
            zip -qr "jshack-nwjs-v${app_version}-win-x64.zip" jshack-nwjs-win-x64
            zip -qry "jshack-nwjs-v${app_version}-osx-arm64.zip" jshack-nwjs-osx-arm64
          )

      - name: Verify Archives
        run: |
          app_version="${{ steps.versions.outputs.app_version }}"
          unzip -Z1 "dist/jshack-v${app_version}.zip" \
            | grep -q 'app/index.html$'
          test -f "dist/jshack-nwjs-v${app_version}-linux-x64.tar.gz"
          unzip -Z1 "dist/jshack-nwjs-v${app_version}-win-x64.zip" \
            | grep -q 'runtime/jshack.exe$'
          unzip -Z1 "dist/jshack-nwjs-v${app_version}-osx-arm64.zip" \
            | grep -q 'runtime/JSHack.app/Contents/Resources/app.nw/package.json$'

      - name: Publish GitHub Release
        env:
          GH_TOKEN: ${{ github.token }}
        run: |
          app_version="${{ steps.versions.outputs.app_version }}"
          release_tag="${{ steps.versions.outputs.release_tag }}"
          if ! gh release view "$release_tag" >/dev/null 2>&1; then
            gh release create "$release_tag" \
              --title "JSHack ${app_version}" \
              --notes "NW.js ${NWJS_VERSION} desktop packages for JSHack ${app_version}."
          fi
          gh release upload "$release_tag" \
            "dist/jshack-v${app_version}.zip" \
            "dist/jshack-nwjs-v${app_version}-linux-x64.tar.gz" \
            "dist/jshack-nwjs-v${app_version}-win-x64.zip" \
            "dist/jshack-nwjs-v${app_version}-osx-arm64.zip" \
            --clobber
# NW.js Wrapper

This directory owns the desktop wrapping mechanics for JSHack. The browser app remains canonical; NW.js is only a containment/distribution shell around `index.html`.

## Stage the App

```sh
deno task wrap:nwjs
```

This writes `dist/nwjs/app/` with:

- the existing browser entry files
- `src/`
- `assets/`
- an NW.js `package.json`

Run that staged app with a local NW.js runtime:

```sh
/path/to/nw dist/nwjs/app
```

## Stage with an Unpacked Runtime

Download and unpack the NW.js runtime for the target platform yourself, then run:

```sh
deno task wrap:nwjs --runtime /path/to/nwjs-runtime
```

The task copies the runtime into `dist/nwjs/runtime/` and places the app in `dist/nwjs/runtime/package.nw/`, which is the platform-specific folder you distribute.

For macOS runtimes, the task detects the `.app` bundle and places the app at:

```text
runtime/JSHack.app/Contents/Resources/app.nw/
```

For Windows runtimes, the task creates a `jshack.exe` launcher beside `nw.exe`.

Current release archive naming:

```text
dist/jshack-nwjs-v<version>-linux-x64.tar.gz
dist/jshack-nwjs-v<version>-win-x64.zip
dist/jshack-nwjs-v<version>-osx-arm64.zip
```

## Boundaries

- Do not import NW.js APIs from `src/rules/`, `src/bridge/`, `src/display/`, or `src/main/`.
- Keep desktop-only files in `packaging/nwjs/`.
- Keep `index.html` runnable in a normal browser.
- Do not add a build step for local game development.
// @ts-check

const ROOT = new URL("../../", import.meta.url);
const DEFAULT_OUT = "dist/nwjs";
const APP_DIR_NAME = "app";
const PACKAGE_NW_DIR_NAME = "package.nw";

const STAGED_PATHS = Object.freeze([
  "index.html",
  "manifest.json",
  "sw.js",
  "icon.svg",
  "logo.jpg",
  "VERSION",
  "src",
  "assets",
]);

const SKIPPED_NAMES = new Set([
  ".git",
  ".github",
  ".DS_Store",
  ".gitignore",
  "Thumbs.db",
  "node_modules",
  "play_all_wavs.sh",
]);

const SKIPPED_SUFFIXES = Object.freeze([
  ".zip",
  "_orig.mp3",
  "_orig.wav",
]);

export function parseArgs(args) {
  const options = {
    out: DEFAULT_OUT,
    runtime: "",
    appName: "JSHack",
    clean: true,
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === "--out") {
      options.out = requireValue(args, ++i, arg);
    } else if (arg.startsWith("--out=")) {
      options.out = arg.slice("--out=".length);
    } else if (arg === "--runtime") {
      options.runtime = requireValue(args, ++i, arg);
    } else if (arg.startsWith("--runtime=")) {
      options.runtime = arg.slice("--runtime=".length);
    } else if (arg === "--app-name") {
      options.appName = requireValue(args, ++i, arg);
    } else if (arg.startsWith("--app-name=")) {
      options.appName = arg.slice("--app-name=".length);
    } else if (arg === "--no-clean") {
      options.clean = false;
    } else if (arg === "--help" || arg === "-h") {
      options.help = true;
    } else {
      throw new Error(`Unknown option: ${arg}`);
    }
  }

  return options;
}

function requireValue(args, index, flag) {
  const value = args[index];
  if (!value || value.startsWith("--")) {
    throw new Error(`${flag} requires a value`);
  }
  return value;
}

export function buildNwManifest({ appName = "JSHack", version = "" } = {}) {
  const manifest = {
    name: appName.toLowerCase().replace(/[^a-z0-9_.-]+/g, "-").replace(
      /^-+|-+$/g,
      "",
    ) || "jshack",
    version: sanitizeVersion(version),
    main: "index.html",
    description:
      "A browser roguelike packaged as a thin NW.js desktop wrapper.",
    window: {
      title: appName,
      icon: "icon.svg",
      width: 1280,
      height: 720,
      min_width: 360,
      min_height: 640,
      resizable: true,
    },
    "chromium-args": "--disable-features=ElasticOverscroll",
  };
  return manifest;
}

function sanitizeVersion(version) {
  const clean = String(version || "").trim();
  return /^\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?$/.test(clean) ? clean : "0.0.0";
}

export function shouldSkipPath(pathPart) {
  if (!pathPart) return false;
  const parts = pathPart.split(/[\\/]+/).filter(Boolean);
  return parts.some((part) => {
    if (SKIPPED_NAMES.has(part)) return true;
    return SKIPPED_SUFFIXES.some((suffix) => part.endsWith(suffix));
  });
}

async function main(args) {
  const options = parseArgs(args);
  if (options.help) {
    printHelp();
    return;
  }

  const outDir = resolveFromRoot(options.out);
  const runtimeDir = options.runtime
    ? resolveMaybeRelative(options.runtime)
    : "";
  if (runtimeDir && options.clean && isSubPath(runtimeDir, outDir)) {
    throw new Error(
      `Refusing to clean ${
        fromCwd(outDir)
      } because --runtime is inside it. Use --no-clean, a different --out, or keep downloaded runtimes outside the output directory.`,
    );
  }
  const appDir = joinPath(outDir, APP_DIR_NAME);
  const version = await readTextIfExists(resolveFromRoot("VERSION"));
  const manifest = buildNwManifest({ appName: options.appName, version });

  if (options.clean) {
    await Deno.remove(outDir, { recursive: true }).catch((err) => {
      if (!(err instanceof Deno.errors.NotFound)) throw err;
    });
  }

  await ensureDir(appDir);
  for (const rel of STAGED_PATHS) {
    await copyPath(resolveFromRoot(rel), joinPath(appDir, rel), rel);
  }
  await writeJson(joinPath(appDir, "package.json"), manifest);

  console.log(`NW.js app staged at ${fromCwd(appDir)}`);

  if (options.runtime) {
    const bundleDir = joinPath(outDir, "runtime");
    await copyPath(runtimeDir, bundleDir, "");
    const runtimeAppDir = await findRuntimeAppDir(bundleDir);
    const packageDir = runtimeAppDir
      ? joinPath(runtimeAppDir, "Contents", "Resources", "app.nw")
      : joinPath(bundleDir, PACKAGE_NW_DIR_NAME);
    await Deno.remove(packageDir, { recursive: true }).catch((err) => {
      if (!(err instanceof Deno.errors.NotFound)) throw err;
    });
    await copyPath(appDir, packageDir, "");
    await installRuntimeLauncher(
      bundleDir,
      manifest.name,
      runtimeAppDir,
      options.appName,
    );
    console.log(`NW.js runtime bundle staged at ${fromCwd(bundleDir)}`);
  }
}

function printHelp() {
  console.log(`Usage: deno task wrap:nwjs [options]

Stages JSHack as a thin NW.js app without changing the browser runtime.

Options:
  --out <dir>        Output directory. Default: ${DEFAULT_OUT}
  --runtime <dir>    Optional unpacked NW.js runtime directory to copy and fill with package.nw
  --app-name <name>  Desktop window/app name. Default: JSHack
  --no-clean         Do not delete the output directory before staging
  -h, --help         Show this help
`);
}

async function copyPath(src, dest, rel) {
  if (shouldSkipPath(rel)) return;
  const info = await Deno.lstat(src);
  if (info.isSymlink) {
    await ensureDir(dirname(dest));
    const target = await Deno.readLink(src);
    await Deno.remove(dest).catch((err) => {
      if (!(err instanceof Deno.errors.NotFound)) throw err;
    });
    await Deno.symlink(target, dest).catch(async () => {
      const resolved = target.startsWith("/")
        ? target
        : joinPath(dirname(src), target);
      await copyPath(resolved, dest, rel);
    });
    return;
  }
  if (info.isDirectory) {
    await ensureDir(dest);
    for await (const entry of Deno.readDir(src)) {
      const nextRel = rel ? `${rel}/${entry.name}` : entry.name;
      if (shouldSkipPath(nextRel)) continue;
      await copyPath(
        joinPath(src, entry.name),
        joinPath(dest, entry.name),
        nextRel,
      );
    }
    return;
  }
  if (!info.isFile) return;
  await ensureDir(dirname(dest));
  await Deno.copyFile(src, dest);
}

async function writeJson(path, value) {
  await ensureDir(dirname(path));
  await Deno.writeTextFile(path, `${JSON.stringify(value, null, 2)}\n`);
}

async function installRuntimeLauncher(
  bundleDir,
  appName,
  runtimeAppDir = "",
  displayAppName = appName,
) {
  if (runtimeAppDir) {
    const appParent = dirname(runtimeAppDir);
    const appDest = joinPath(
      appParent,
      `${toDisplayAppName(displayAppName)}.app`,
    );
    if (appDest !== runtimeAppDir) {
      await Deno.remove(appDest, { recursive: true }).catch((err) => {
        if (!(err instanceof Deno.errors.NotFound)) throw err;
      });
      await Deno.rename(runtimeAppDir, appDest);
    }
    return;
  }

  const linuxNw = joinPath(bundleDir, "nw");
  if (await isFile(linuxNw)) {
    const launcher = joinPath(bundleDir, appName);
    if (launcher !== linuxNw) {
      await Deno.copyFile(linuxNw, launcher);
      await Deno.chmod(launcher, 0o755).catch(() => {});
    }
    return;
  }

  const winNw = joinPath(bundleDir, "nw.exe");
  if (await isFile(winNw)) {
    const launcher = joinPath(bundleDir, `${appName}.exe`);
    if (launcher !== winNw) {
      await Deno.copyFile(winNw, launcher);
    }
  }
}

function toDisplayAppName(appName) {
  const clean = String(appName || "").trim();
  if (!clean) return "JSHack";
  return clean.replace(/[/:\\]/g, "-");
}

async function findRuntimeAppDir(bundleDir) {
  for await (const entry of Deno.readDir(bundleDir)) {
    if (!entry.isDirectory || !entry.name.endsWith(".app")) continue;
    const appDir = joinPath(bundleDir, entry.name);
    if (await isDirectory(joinPath(appDir, "Contents", "Resources"))) {
      return appDir;
    }
  }
  return "";
