import { DungeonState } from '../components/DungeonState.js';
import { DeathApplied } from '../components/DeathApplied.js';
import { Player } from '../components/Player.js';
import { Score } from '../components/Score.js';
import { Vitality } from '../components/Vitality.js';

/**
 * Award the dead entity's maxHp to the player's score,
 * multiplied by the current floor depth.
 * @param {import('../../lib/ecs-js/index.js').World} world
 */
export function scoreSystem(world) {
  for (const [, death] of world.query(DeathApplied)) {
    const id = Number(death.target || 0) | 0;
    const killer = Number(death.killer || 0) | 0;
    // Only score kills made by the player
    if (!killer || !world.has(killer, Player)) continue;
    // Don't score the player's own death
    if (world.has(id, Player)) continue;

    const vit = world.get(id, Vitality);
    if (!vit) continue;

    const score = world.get(killer, Score);
    if (!score) continue;

    let depth = 1;
    for (const [, ds] of world.query(DungeonState)) { depth = ds.currentDepth || 1; break; }

    score.current += vit.maxHp * depth;
  }
}
import { normalizeGridPoint } from "../../shared/math/point.js";
import { DeathApplied } from "../components/DeathApplied.js";
import { Lifespan } from "../components/Lifespan.js";

/**
 * Create a one-turn death record for scheduled rules-side reactions.
 *
 * @param {import("../../lib/ecs-js/index.js").World} world
 * @param {Partial<DeathApplied["defaults"]>} data
 * @returns {number}
 */
export function recordDeathApplied(world, data) {
  const id = world.create();
  world.add(id, DeathApplied, {
    ...data,
    target: Number(data.target || data.id || 0) | 0,
    killer: Number(data.killer || 0) | 0,
    cause: String(data.cause || ""),
    weaponId: Number(data.weaponId || 0) | 0,
    weaponFamily: String(data.weaponFamily || ""),
    damageType: String(data.damageType || ""),
    critical: !!data.critical,
    amount: Number(data.amount || 0) | 0,
    goreType: String(data.goreType || ""),
    sizeClass: String(data.sizeClass || ""),
    targetKind: String(data.targetKind || ""),
    at: normalizeGridPoint(data.at),
    step: Number(data.step ?? world.step ?? 0) | 0,
  });
  world.add(id, Lifespan, { turnsLeft: 1, onExpiry: "remove", expiryEvent: "" });
  return id;
}
import { defineComponent } from "../../lib/ecs-js/index.js";

/**
 * Owner component for tracking entity ownership.
 * @property {string} ownerId - The ID of the owning entity (e.g., player, container).
 */
export const Owner = defineComponent(
  "Owner",
  {
    ownerId: null
  },
  {
    validate(rec) {
      // Accept number (entity id) or non-empty string
      return (
        (typeof rec.ownerId === "number" && Number.isFinite(rec.ownerId) && rec.ownerId >= 0) ||
        (typeof rec.ownerId === "string" && rec.ownerId.length > 0)
      );
    }
  }
);
import { defineTag } from '../../lib/ecs-js/index.js';

/**
 * Pet component tag — marks an entity as a player's pet.
 */
export const Pet = defineTag('Pet');
import { assertEquals } from "jsr:@std/assert";
import { World } from "../src/lib/ecs-js/index.js";
import { DungeonState } from "../src/rules/components/DungeonState.js";
import { Player } from "../src/rules/components/Player.js";
import { Score } from "../src/rules/components/Score.js";
import { Vitality } from "../src/rules/components/Vitality.js";
import { scoreSystem } from "../src/rules/systems/scoreSystem.js";
import { recordDeathApplied } from "../src/rules/utils/deathApplied.js";

Deno.test("scoreSystem awards player kills from DeathApplied records", () => {
  const world = new World({ seed: 1 });

  const dungeon = world.create();
  world.add(dungeon, DungeonState, { currentDepth: 3 });

  const player = world.create();
  world.add(player, Player);
  world.add(player, Score, { current: 10 });

  const monster = world.create();
  world.add(monster, Vitality, { hp: 0, maxHp: 7 });

  recordDeathApplied(world, { target: monster, killer: player });
  scoreSystem(world);

  assertEquals(world.get(player, Score).current, 31);
});

Deno.test("scoreSystem ignores non-player kills and player deaths", () => {
  const world = new World({ seed: 1 });

  const player = world.create();
  world.add(player, Player);
  world.add(player, Score, { current: 5 });
  world.add(player, Vitality, { hp: 0, maxHp: 20 });

  const monster = world.create();
  world.add(monster, Vitality, { hp: 10, maxHp: 10 });

  recordDeathApplied(world, { target: monster, killer: 0 });
  recordDeathApplied(world, { target: player, killer: monster });
  scoreSystem(world);

  assertEquals(world.get(player, Score).current, 5);
});
